html:
{%- set firma = frappe.get_doc("Company", doc.company) -%}
{%- set absender = frappe.get_doc("Address", doc.company_address) if doc.company_address else None -%}
{%- set empf = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None -%}
{%- set bankkonto = frappe.db.get_value("Bank Account", firma.default_bank_account, ["iban", "bank"], as_dict=True) if firma.default_bank_account else None -%}
{%- set bic = frappe.db.get_value("Bank", bankkonto.bank, "swift_number") if bankkonto and bankkonto.bank else "" -%}
{%- set leistungsdatum = doc.to_date or doc.posting_date -%}
{%- set uom_de = {"Hour": "Std.", "Nos": "Stk.", "Day": "Tag", "Week": "Woche", "Month": "Monat", "Unit": "Einheit", "Set": "Set", "Kilometer": "km"} -%}
<style>
  .rg { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; font-size: 10.5pt; color: #111827; line-height: 1.45; }
  .rg table { border-collapse: collapse; width: 100%; }
  .rg .kopf { border-bottom: 2px solid #111827; padding-bottom: 8px; margin-bottom: 22px; }
  .rg .kopf .name { font-size: 17pt; font-weight: 700; letter-spacing: .01em; }
  .rg .kopf .zusatz { font-size: 9pt; color: #4b5563; margin-top: 2px; }
  .rg .kopf .rechts { text-align: right; font-size: 9pt; color: #4b5563; line-height: 1.5; }
  .rg .empfaenger { width: 62%; vertical-align: top; }
  .rg .empfaenger .label { font-size: 7.5pt; text-transform: uppercase; letter-spacing: .08em; color: #6b7280; margin-bottom: 3px; }
  .rg .empfaenger .anschrift { font-size: 11pt; }
  .rg .daten { width: 38%; vertical-align: top; }
  .rg .daten td { padding: 1.5px 0; font-size: 9.5pt; }
  .rg .daten td.k { color: #6b7280; padding-right: 10px; white-space: nowrap; }
  .rg .daten td.v { text-align: right; font-weight: 600; white-space: nowrap; }
  .rg h1 { font-size: 14pt; margin: 26px 0 4px; font-weight: 700; }
  .rg .unterzeile { font-size: 9pt; color: #4b5563; margin-bottom: 14px; }
  .rg .positionen { margin-top: 6px; }
  .rg .positionen th { background: #111827; color: #fff; font-size: 8.5pt; text-transform: uppercase; letter-spacing: .05em; padding: 6px 7px; text-align: left; }
  .rg .positionen th.r, .rg .positionen td.r { text-align: right; }
  .rg .positionen td { padding: 6px 7px; border-bottom: 1px solid #e5e7eb; vertical-align: top; font-size: 10pt; }
  .rg .positionen .pos-nr { width: 7%; color: #6b7280; }
  .rg .positionen .menge { width: 11%; text-align: right; white-space: nowrap; }
  .rg .positionen .einzel { width: 17%; text-align: right; white-space: nowrap; }
  .rg .positionen .summe { width: 17%; text-align: right; white-space: nowrap; }
  .rg .beschreibung { font-size: 8.5pt; color: #4b5563; margin-top: 2px; white-space: pre-wrap; }
  .rg .summen { width: 45%; margin-left: 55%; margin-top: 10px; }
  .rg .summen td { padding: 3px 7px; font-size: 10pt; }
  .rg .summen td.k { color: #4b5563; }
  .rg .summen td.v { text-align: right; white-space: nowrap; }
  .rg .summen tr.gesamt td { border-top: 2px solid #111827; font-size: 11.5pt; font-weight: 700; padding-top: 6px; }
  .rg .hinweis-ku { margin-top: 16px; padding: 8px 10px; border-left: 3px solid #111827; background: #f3f4f6; font-size: 9.5pt; }
  .rg .block { margin-top: 16px; font-size: 9.5pt; }
  .rg .block .titel { font-size: 8.5pt; text-transform: uppercase; letter-spacing: .06em; color: #6b7280; margin-bottom: 3px; }
  .rg { padding-bottom: 8mm; }
  .rg .fuss { position: fixed; bottom: 0; left: 0; right: 0; margin: 0; padding-top: 5px;
              border-top: 1px solid #9ca3af; font-size: 7.5pt; color: #6b7280; line-height: 1.35; }
  .rg .fuss td { padding: 0; vertical-align: bottom; }
  .rg .fuss .l { text-align: left; }
  .rg .fuss .r { text-align: right; white-space: nowrap; padding-left: 10px; }
</style>

<div class="rg">

  <table class="kopf">
    <tr>
      <td>
        <div class="name">{{ (firma.company_name or doc.company)|e }}</div>
        <div class="zusatz">
          {% if firma.company_description %}{{ firma.company_description|e }}{% endif %}
        </div>
      </td>
      <td class="rechts">
        {% if firma.email %}{{ firma.email|e }}<br>{% endif %}
        {% if firma.website %}{{ firma.website|e }}{% endif %}
      </td>
    </tr>
  </table>

  <table>
    <tr>
      <td class="empfaenger">
        <div class="label">Rechnungsempfänger</div>
        <div class="anschrift">
          <b>{{ (doc.customer_name or doc.customer)|e }}</b><br>
          {% if empf %}
            {% if empf.address_line1 %}{{ empf.address_line1|e }}<br>{% endif %}
            {% if empf.address_line2 %}{{ empf.address_line2|e }}<br>{% endif %}
            {{ (empf.pincode or "")|e }} {{ (empf.city or "")|e }}<br>
            {{ ("Deutschland" if empf.country == "Germany" else _(empf.country))|e }}
          {% endif %}
          {% if doc.customer and frappe.db.get_value('Customer', doc.customer, 'tax_id') %}<br>USt-IdNr.: {{ frappe.db.get_value('Customer', doc.customer, 'tax_id')|e }}{% endif %}
        </div>
      </td>
      <td class="daten">
        <table>
          <tr><td class="k">Rechnungsnummer</td><td class="v">{{ doc.name|e }}</td></tr>
          <tr><td class="k">Rechnungsdatum</td><td class="v">{{ frappe.utils.format_date(doc.posting_date) }}</td></tr>
          <tr><td class="k">Leistungsdatum</td><td class="v">{{ frappe.utils.format_date(leistungsdatum) }}</td></tr>
          {% if doc.from_date and doc.from_date != leistungsdatum %}
          <tr><td class="k">Leistungszeitraum</td><td class="v">{{ frappe.utils.format_date(doc.from_date) }} &ndash; {{ frappe.utils.format_date(leistungsdatum) }}</td></tr>
          {% endif %}
          {% if doc.customer %}
          <tr><td class="k">Kundennummer</td><td class="v">{{ doc.customer|e }}</td></tr>
          {% endif %}
          {% if doc.buyer_reference %}
          <tr><td class="k">Ihre Referenz</td><td class="v">{{ doc.buyer_reference|e }}</td></tr>
          {% endif %}
          <tr><td class="k">Fällig am</td><td class="v">{{ frappe.utils.format_date(doc.due_date) if doc.due_date else frappe.utils.format_date(doc.posting_date) }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <h1>Rechnung {{ doc.name|e }}</h1>
  <div class="unterzeile">
    Leistungsdatum: {{ frappe.utils.format_date(leistungsdatum) }}
    {% if doc.project %} &middot; Projekt: {{ doc.project|e }}{% endif %}
    {% if doc.po_no %} &middot; Ihre Bestellung: {{ doc.po_no|e }}{% endif %}
  </div>

  <table class="positionen">
    <thead>
      <tr>
        <th class="pos-nr">Pos.</th>
        <th>Bezeichnung</th>
        <th class="menge">Menge</th>
        <th class="einzel">Einzelpreis</th>
        <th class="summe">Betrag</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="pos-nr">{{ row.idx|e }}</td>
        <td>
          <b>{{ (row.item_name or row.item_code)|e }}</b>
          {% if row.description and row.description != row.item_name %}
          <div class="beschreibung">{{ html_zu_text(row.description)|e }}</div>
          {% endif %}
        </td>
        <td class="menge">{{ frappe.utils.fmt_money(row.qty, 2) }} {{ uom_de.get(row.uom, row.uom or '')|e }}</td>
        <td class="einzel">{{ frappe.utils.fmt_money(row.rate, currency=doc.currency) }}</td>
        <td class="summe">{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="summen">
    <tr>
      <td class="k">Nettobetrag</td>
      <td class="v">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</td>
    </tr>
    {% if doc.total_taxes_and_charges %}
    <tr>
      <td class="k">Umsatzsteuer</td>
      <td class="v">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) }}</td>
    </tr>
    {% endif %}
    <tr class="gesamt">
      <td class="k">Rechnungsbetrag</td>
      <td class="v">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td>
    </tr>
  </table>

  <div class="hinweis-ku">
    <b>{{ (frappe.db.get_single_value("E Invoice Settings", "vat_exemption_reason_text") or "Kein Ausweis von Umsatzsteuer, da Kleinunternehmer gemäß § 19 UStG")|e }}.</b>
    Es wird daher keine Umsatzsteuer in der Rechnung ausgewiesen.
  </div>

  <div class="block">
    <div class="titel">Zahlungsbedingungen</div>
    {% set tage = frappe.utils.date_diff(doc.due_date, doc.posting_date) if doc.due_date else 0 %}
    Zahlbar ohne Abzug{% if tage and tage > 0 %} innerhalb von {{ tage|e }} Tagen{% endif %}{% if doc.due_date %} bis zum {{ frappe.utils.format_date(doc.due_date) }}{% endif %}.
    {% if bankkonto and bankkonto.iban %}
      <br>
      <b>Bankverbindung:</b> {{ (bankkonto.bank or "")|e }} &middot; IBAN {{ bankkonto.iban|e }}{% if bic %} &middot; BIC {{ bic|e }}{% endif %}
      &middot; Kontoinhaber: {{ (firma.company_name or doc.company)|e }}
      <br>
      <b>Verwendungszweck:</b> {{ doc.name|e }}
    {% else %}
      <br>Bankverbindung auf Anfrage.
    {% endif %}
  </div>

  {% if doc.einvoice_profile %}
  <div class="block">
    <div class="titel">Elektronische Rechnung</div>
    {% if doc.einvoice_profile == "XRECHNUNG" %}
      Diese Rechnung ist eine E-Rechnung im Format XRechnung (EN 16931). Das strukturierte XML-Dokument
      wird mit der Rechnung übermittelt und ist maschinell lesbar.
    {% else %}
      Diese Rechnung ist eine E-Rechnung im Format ZUGFeRD / Factur-X, Profil {{ doc.einvoice_profile|e }}. Das strukturierte XML ist in diese PDF-Datei eingebettet und maschinell lesbar.
    {% endif %}
  </div>
  {% endif %}

  <div id="footer-html">
<table style="margin-top:-15mm; width:100%; border-collapse:collapse; font-family:Helvetica,Arial,sans-serif; font-size:7.5pt; color:#6b7280; line-height:1.35; border-top:1px solid #9ca3af; padding-top:4px;">

    <tr>
      <td style="vertical-align:bottom;">
        <b>{{ (firma.company_name or doc.company)|e }}</b>
        {% if absender %} &middot; {{ absender.address_line1|e }}, {{ absender.pincode|e }} {{ absender.city|e }}{% endif %}
        {% if firma.phone_no or firma.phone %}&middot; Tel. {{ (firma.phone_no or firma.phone)|e }}{% endif %}
        {% if firma.email %} &middot; {{ firma.email|e }}{% endif %}
        {% if firma.website %} &middot; {{ firma.website|e }}{% endif %}
        <br>
        {% if firma.tax_id %}USt-IdNr.: {{ firma.tax_id|e }}{% endif %}
        {% if bankkonto and bankkonto.iban %}&middot; {{ (bankkonto.bank or "")|e }} &middot; IBAN {{ bankkonto.iban|e }}{% if bic %} &middot; BIC {{ bic|e }}{% endif %}{% endif %}
      </td>
      <td style="vertical-align:bottom; text-align:right; white-space:nowrap;">Seite <span class="page"></span> von <span class="topage"></span></td>
    </tr>
  </table>
</div>

</div>
